/* 翻译:中文是数据里的原文,显示时按设置转成 English / 日本語(DOM 后处理)。
   UI 设置由应用在启动时通过 bindUI 提供,这里不直接依赖应用状态。 */
/* 替换函数的参数是正则捕获组(字符串),有的规则直接拿它做数字运算,所以这里用 any */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Rule = [RegExp, string | ((...a: any[]) => string)];
type UIView = { lang?: string } | undefined;
let uiGet: () => UIView = () => undefined;
export const bindUI = (f: () => UIView): void => { uiGet = f; };
