export function trx(t:string,lg:string):string{
 if(!/[　-〿一-鿿＀-￯]/.test(t))return t;
 const ja=lg==='ja',DC=ja?ZH2JA:ZH2EN,KS=ja?ZKJ:ZK,XC=ja?ZX_JA:ZX_EN,RR=ja?RX_JA:RX;
 const m=t.match(/^(\s*)([\s\S]*?)(\s*)$/)!;let s=m[2]; /* 这个正则对任何字符串都能匹配 */
 if(DC[s]!==undefined)return m[1]+DC[s]+m[3];
 if(XC[s]!==undefined)return m[1]+XC[s]+m[3];
 for(const [r,f] of RR)s=s.replace(r,f as string);
 for(const k of KS)if(s.includes(k))s=s.split(k).join(DC[k]);
 if(ja)s=s.replace(/，/g,'、').replace(/：/g,':').replace(/（/g,'(').replace(/）/g,')');
 else s=s.replace(/，/g,', ').replace(/、/g,', ').replace(/。/g,'. ').replace(/：/g,': ').replace(/「|」/g,'"').replace(/（/g,'(').replace(/）/g,')');
 return m[1]+s.replace(/\s+$/,m[3]?'':'')+m[3];
}
export const LG=()=>{const l=(uiGet()&&uiGet()!.lang)||'zh';if(l==='auto'){const n=navigator.language||'';return /^zh/i.test(n)?'zh':/^ja/i.test(n)?'ja':'en'}return l==='en'?'en':l==='ja'?'ja':'zh'};
export function trs(t:string):string{
 if(!uiGet()||LG()==='zh')return t.replace(/[\uE000\uE001]/g,'');
 const lg=LG();
 return t.split(/(\uE000[^\uE001]*\uE001)/).map(g=>g.charCodeAt(0)===0xE000?g.slice(1,-1):trx(g,lg)).join('');
}
